function safeLesson(value){try{if(!value)return null;const lesson=C.parseLesson(JSON.stringify({resumen:value.summary,tarjetas:value.cards?.map(c=>({pregunta:c.question,respuesta:c.answer})),guion:value.script}));if(value.outline){try{lesson.outline=C.parseOutline(JSON.stringify({esquema:value.outline.map(s=>({titulo:s.title,puntos:s.points}))}));}catch(_){/* Ignore an invalid optional outline. */}}return lesson;}catch(_){return null;}}
function manualPrompt(kind,m){const schemas={lesson:'{"resumen":["idea 1","idea 2","idea 3"],"tarjetas":[{"pregunta":"...","respuesta":"..."},{"pregunta":"...","respuesta":"..."},{"pregunta":"...","respuesta":"..."}],"guion":"Texto narrado"}',outline:'{"esquema":[{"titulo":"Apartado 1","puntos":["Punto 1","Punto 2"]},{"titulo":"Apartado 2","puntos":["Punto 1","Punto 2"]},{"titulo":"Apartado 3","puntos":["Punto 1","Punto 2"]}]}',quiz:'{"preguntas":[{"pregunta":"...","opciones":["A","B","C","D"],"correcta":0,"explicacion":"..."}]}'};return `Actúa como profesor. Usa solo el material adjunto, no inventes datos y comprueba las respuestas. Crea ${kind==='lesson'?'una lección con 3 a 5 ideas y tarjetas y un guion de hasta 3000 caracteres':kind==='outline'?'un esquema con al menos 3 apartados':'un examen con 5 preguntas variadas de clase, 4 opciones por pregunta y una respuesta correcta (índice 0 a 3)'}. Responde SOLO con JSON válido, sin Markdown, siguiendo esta estructura: ${schemas[kind]}. MATERIAL (${m.name}):\n${m.text.slice(0,21000)}`;}
function manualPanel(kind,m){if(!m)return '';const title={lesson:'lección y tarjetas',outline:'esquema',quiz:'examen'}[kind];return `<section class="panel"><h2>ChatGPT sin clave API · ${title}</h2><p>1. Copia la petición. 2. Pégala en ChatGPT. 3. Copia su respuesta completa y pégala aquí.</p><p class="tiny">Tu material solo saldrá de FocusForge si tú lo pegas en ChatGPT. Comprueba las respuestas con tus apuntes. Se copian hasta 21 000 caracteres.</p><div class="actions"><button type="button" class="button primary" data-manual-copy="${kind}">Copiar petición</button><a class="button" href="https://chatgpt.com/" rel="noopener noreferrer">Abrir ChatGPT ↗</a></div><textarea id="manual-prompt-${kind}" readonly hidden aria-label="Petición para ChatGPT"></textarea><div class="field"><label for="manual-answer-${kind}">Respuesta JSON de ChatGPT</label><textarea id="manual-answer-${kind}" rows="7" placeholder="Pega la respuesta completa con las llaves { }"></textarea></div><button type="button" class="button primary" data-manual-save="${kind}">Guardar ${title}</button></section>`;}
